CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;

DO $$ BEGIN CREATE TYPE "Role" AS ENUM ('OWNER','ADMIN','MEMBER','VIEWER'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "AgentStatus" AS ENUM ('DRAFT','TESTING','DEPLOYED','PAUSED','ARCHIVED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "ConversationSource" AS ENUM ('DASHBOARD_TEST','WEBSITE_WIDGET','API','WHATSAPP_PLACEHOLDER','EMAIL_PLACEHOLDER'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "MessageRole" AS ENUM ('USER','ASSISTANT','SYSTEM','TOOL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "HumanApprovalStatus" AS ENUM ('PENDING','APPROVED','REJECTED','EXPIRED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "SubscriptionPlan" AS ENUM ('FREE','STARTER','PRO','BUSINESS'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "DocumentStatus" AS ENUM ('PROCESSING','READY','FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "DeploymentStatus" AS ENUM ('ACTIVE','PAUSED','DISABLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS "User" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "email" text UNIQUE NOT NULL, "name" text, "passwordHash" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "Organization" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "OrganizationMember" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "userId" uuid NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "role" "Role" NOT NULL DEFAULT 'MEMBER', "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("organizationId","userId"));
CREATE INDEX IF NOT EXISTS "OrganizationMember_userId_idx" ON "OrganizationMember"("userId");
CREATE TABLE IF NOT EXISTS "Session" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" uuid NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "tokenHash" text UNIQUE NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "PasswordResetToken" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "email" text NOT NULL, "tokenHash" text UNIQUE NOT NULL, "expiresAt" timestamptz NOT NULL, "usedAt" timestamptz, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "Subscription" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "plan" "SubscriptionPlan" NOT NULL DEFAULT 'FREE', "stripeCustomerId" text, "stripeSubscriptionId" text, "status" text NOT NULL DEFAULT 'free', "currentPeriodEnd" timestamptz, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "Subscription_organizationId_idx" ON "Subscription"("organizationId");

CREATE TABLE IF NOT EXISTS "CategoryPack" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "slug" text UNIQUE NOT NULL, "name" text NOT NULL, "description" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "AgentTemplate" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "categoryPackId" uuid NOT NULL REFERENCES "CategoryPack"("id") ON DELETE CASCADE, "slug" text NOT NULL, "name" text NOT NULL, "description" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("categoryPackId","slug"));
CREATE TABLE IF NOT EXISTS "SetupQuestion" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "categoryPackId" uuid NOT NULL REFERENCES "CategoryPack"("id") ON DELETE CASCADE, "prompt" text NOT NULL, "inputType" text NOT NULL DEFAULT 'text', "options" jsonb, "sortOrder" integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "ToolDefinition" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text UNIQUE NOT NULL, "description" text NOT NULL, "category" text NOT NULL, "riskLevel" text NOT NULL DEFAULT 'low', "requiresApproval" boolean NOT NULL DEFAULT false, "enabledByDefault" boolean NOT NULL DEFAULT true, "inputSchema" jsonb NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS "Agent" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "categorySlug" text NOT NULL, "templateId" uuid REFERENCES "AgentTemplate"("id"), "name" text NOT NULL, "description" text, "status" "AgentStatus" NOT NULL DEFAULT 'DRAFT', "setupAnswers" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "Agent_organizationId_idx" ON "Agent"("organizationId");
CREATE TABLE IF NOT EXISTS "AgentBlueprint" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "version" integer NOT NULL DEFAULT 1, "content" jsonb NOT NULL, "promptMetadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "AgentBlueprint_organizationId_agentId_idx" ON "AgentBlueprint"("organizationId","agentId");
CREATE TABLE IF NOT EXISTS "AgentVersion" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "version" integer NOT NULL, "snapshot" jsonb NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "AgentDeployment" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "publicKey" text UNIQUE NOT NULL, "allowedDomains" text[] NOT NULL DEFAULT ARRAY[]::text[], "status" "DeploymentStatus" NOT NULL DEFAULT 'ACTIVE', "widgetSettings" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS "KnowledgeSource" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid, "name" text NOT NULL, "sourceType" text NOT NULL, "metadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "Document" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "fileName" text NOT NULL, "mimeType" text NOT NULL, "storagePath" text NOT NULL, "sizeBytes" integer NOT NULL, "status" "DocumentStatus" NOT NULL DEFAULT 'PROCESSING', "error" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "DocumentChunk" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "documentId" uuid NOT NULL REFERENCES "Document"("id") ON DELETE CASCADE, "content" text NOT NULL, "metadata" jsonb, "tokenCount" integer NOT NULL, "embedding" vector(1536), "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "DocumentChunk_organizationId_agentId_idx" ON "DocumentChunk"("organizationId","agentId");
CREATE INDEX IF NOT EXISTS document_chunk_embedding_idx ON "DocumentChunk" USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

CREATE TABLE IF NOT EXISTS "Conversation" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "source" "ConversationSource" NOT NULL DEFAULT 'DASHBOARD_TEST', "visitorId" text, "title" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "Message" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "conversationId" uuid NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE, "role" "MessageRole" NOT NULL, "content" text NOT NULL, "metadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "ToolCall" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "conversationId" uuid REFERENCES "Conversation"("id") ON DELETE SET NULL, "toolName" text NOT NULL, "arguments" jsonb NOT NULL, "status" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "ToolResult" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "toolCallId" uuid UNIQUE NOT NULL REFERENCES "ToolCall"("id") ON DELETE CASCADE, "result" jsonb NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "HumanApproval" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL, "conversationId" uuid REFERENCES "Conversation"("id") ON DELETE SET NULL, "toolName" text NOT NULL, "requestedAction" text NOT NULL, "proposedArguments" jsonb NOT NULL, "riskLevel" text NOT NULL, "status" "HumanApprovalStatus" NOT NULL DEFAULT 'PENDING', "requestedByMessageId" uuid, "approvedByUserId" uuid REFERENCES "User"("id"), "rejectedByUserId" uuid REFERENCES "User"("id"), "createdAt" timestamptz NOT NULL DEFAULT now(), "decidedAt" timestamptz);

CREATE TABLE IF NOT EXISTS "Integration" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "provider" text NOT NULL, "status" text NOT NULL DEFAULT 'coming_soon', "config" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "IntegrationCredential" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "provider" text NOT NULL, "encryptedData" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "IntegrationEvent" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "provider" text NOT NULL, "eventType" text NOT NULL, "payload" jsonb NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "AgentTestCase" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "name" text NOT NULL, "input" text NOT NULL, "expected" text NOT NULL, "metadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "AgentTestRun" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid NOT NULL REFERENCES "Agent"("id") ON DELETE CASCADE, "testCaseId" uuid, "input" text NOT NULL, "output" jsonb NOT NULL, "passed" boolean, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "UsageEvent" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "type" text NOT NULL, "quantity" integer NOT NULL DEFAULT 1, "metadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "AuditLog" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "actorUserId" uuid, "action" text NOT NULL, "targetType" text, "targetId" text, "metadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "Lead" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid REFERENCES "Agent"("id") ON DELETE SET NULL, "name" text, "email" text, "phone" text, "status" text NOT NULL DEFAULT 'new', "metadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "Booking" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organizationId" uuid NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "agentId" uuid REFERENCES "Agent"("id") ON DELETE SET NULL, "leadId" uuid, "status" text NOT NULL DEFAULT 'PENDING_APPROVAL', "scheduledFor" timestamptz, "metadata" jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION match_document_chunks(query_embedding vector(1536), match_count int, filter_organization_id uuid, filter_agent_id uuid)
RETURNS TABLE (id uuid, document_id uuid, content text, metadata jsonb, similarity float)
LANGUAGE sql STABLE
AS $$
  SELECT dc.id, dc."documentId" AS document_id, dc.content, dc.metadata::jsonb, 1 - (dc.embedding <=> query_embedding) AS similarity
  FROM "DocumentChunk" dc
  WHERE dc."organizationId" = filter_organization_id
    AND dc."agentId" = filter_agent_id
    AND dc.embedding IS NOT NULL
  ORDER BY dc.embedding <=> query_embedding
  LIMIT match_count;
$$;
